public class Main {
    public static void main(String[] args) {
        int option = 2;
        switch (option) {
            case 1:
                System.out.println("Add");
                break;
            case 2:
                System.out.println("View");
                break;
            default:
                System.out.println("Unknown option");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int code = 404;
        switch (code) {
            case 200:
                System.out.println("OK");
                break;
            case 500:
                System.out.println("Server error");
                break;
            default:
                System.out.println("Other status");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int day = 6;
        switch (day) {
            case 6:
            case 7:
                System.out.println("Weekend");
                break;
            default:
                System.out.println("Weekday");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int day = 3;
        String name = switch (day) {
            case 1 -> "Monday";
            case 2 -> "Tuesday";
            case 3 -> "Wednesday";
            default -> "Other day";
        };
        System.out.println(name);
    }
}

public class Main {
    public static void main(String[] args) {
        int month = 2;
        int days = switch (month) {
            case 4, 6, 9, 11 -> 30;
            case 2 -> 28;
            default -> 31;
        };
        System.out.println(days);
    }
}
